using Cosmos.API.Security;using Cosmos.Application.Abstractions.Services;using Cosmos.Application.PurchaseExpense;using Cosmos.Domain.Security;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace Cosmos.API.Controllers;
[Authorize,Tags("ExpensesController"),ApiExplorerSettings(GroupName="Purchase & Expense"),Route("api/expenses")]
public sealed class ExpensesController(IPurchaseExpenseService s):ApiControllerBase { [HttpGet,RequirePermission("PurchaseExpense.Expense",PermissionAction.View)]public async Task<IActionResult>List([FromQuery]ExpenseListQuery q,CancellationToken ct)=>FromResponse(await s.GetExpensesAsync(q,ct));[HttpGet("{id:long}"),RequirePermission("PurchaseExpense.Expense",PermissionAction.View)]public async Task<IActionResult>Get(long id,CancellationToken ct)=>FromResponse(await s.GetExpenseAsync(id,ct));[HttpPost,RequirePermission("PurchaseExpense.Expense",PermissionAction.Create)]public async Task<IActionResult>Create(CreateExpenseRequest r,CancellationToken ct)=>FromResponse(await s.CreateExpenseAsync(r,ct),201);[HttpPut("{id:long}"),RequirePermission("PurchaseExpense.Expense",PermissionAction.Edit)]public async Task<IActionResult>Update(long id,UpdateExpenseRequest r,CancellationToken ct)=>FromResponse(await s.UpdateExpenseAsync(id,r,ct));[HttpDelete("{id:long}"),RequirePermission("PurchaseExpense.Expense",PermissionAction.Delete)]public async Task<IActionResult>Delete(long id,CancellationToken ct)=>FromResponse(await s.DeleteExpenseAsync(id,ct)); }
